pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        // Assume arrays have same non-zero length
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        // Assume caddress is not the zero address (to avoid trivial revert)
        vm.assume(caddress != address(0));

        // We need a contract at caddress that will not revert on transferFrom
        // Deploy a dummy that always succeeds
        vm.etch(caddress, type(Dummy).runtimeCode);

        // Call transfer
        bool result = c.transfer(from, caddress, _tos, v);

        // The rule: if the call completes (no revert), it must return true
        assertTrue(result);
    }
}

contract Dummy {
    fallback() external payable {}
}

