pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // We need a contract at caddress that will not revert on transferFrom
        // Deploy a dummy ERC20 that allows arbitrary transfers
        vm.assume(caddress != address(0));
        vm.ethereum(caddress, type(uint256).max); // give it code
        // Actually we need to ensure the call succeeds; we can use a mock
        // For simplicity, we cheat by making the call return true via vm.mockCall
        for (uint i = 0; i < _tos.length; i++) {
            vm.mockCall(
                caddress,
                abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, _tos[i], v[i]),
                abi.encode(true)
            );
        }
        // Now call transfer - it should not revert
        bool success;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}

